DROP TABLE IF EXISTS `hn_advlist_city`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hn_advlist_city` (
  `id` bigint(10) NOT NULL AUTO_INCREMENT,
  `aid` int(10) NOT NULL DEFAULT '0' COMMENT '广告ID',
  `cityid` int(10) NOT NULL DEFAULT '0' COMMENT '城市ID',
  `body` text COMMENT '广告内容',
  `admin` int(10) NOT NULL DEFAULT '0' COMMENT '操作人',
  `date` int(10) NOT NULL DEFAULT '0' COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `aid` (`aid`),
  KEY `cityid` (`cityid`),
  KEY `admin` (`admin`),
  KEY `date` (`date`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='城市分站广告';
