--
-- Table structure for table `hn_infotypeitem`
--

DROP TABLE IF EXISTS `hn_infotypeitem`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hn_infotypeitem` (
  `id` int(5) NOT NULL AUTO_INCREMENT,
  `tid` int(5) unsigned NOT NULL DEFAULT '0' COMMENT '分类ID',
  `field` char(20) NOT NULL DEFAULT '0' COMMENT '字段名',
  `title` char(30) NOT NULL DEFAULT '' COMMENT '字段别名',
  `orderby` int(5) NOT NULL DEFAULT '0' COMMENT '排序',
  `formtype` char(10) NOT NULL DEFAULT '50' COMMENT '字段类型',
  `required` smallint(1) NOT NULL DEFAULT '0' COMMENT '是否必填',
  `options` text NOT NULL COMMENT '选项列表',
  `default` char(50) NOT NULL DEFAULT '' COMMENT '默认值',
  `custom` smallint(1) NOT NULL DEFAULT '0' COMMENT '是否自定义',
  `search` smallint(1) unsigned zerofill NOT NULL DEFAULT '0' COMMENT '搜索条件{0否,1是}',
  `heightlight` smallint(1) unsigned zerofill NOT NULL DEFAULT '0' COMMENT '是否高亮{0否,1是}',
  PRIMARY KEY (`id`),
  KEY `tid` (`tid`),
  KEY `field` (`field`)
) ENGINE=MyISAM AUTO_INCREMENT=132 DEFAULT CHARSET=utf8mb4 COMMENT='信息分类字段';
/*!40101 SET character_set_client = @saved_cs_client */;

