  `title` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '公司名称',
  `nature` int(10) NOT NULL DEFAULT '0' COMMENT '公司性质(jobitem)',
  `scale` int(10) NOT NULL DEFAULT '0' COMMENT '公司规模(jobitem)',
  `industry` int(11) NOT NULL DEFAULT '0' COMMENT '经营行业(job_industry)',
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '公司logo',
  `people` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '招聘联系人名称',
  `people_pic` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '联系人头像',
  `random_people_pic` int(2) NOT NULL DEFAULT '0' COMMENT '随机头像地址（如果不为0则为随机头像序号）',
  `people_job` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '招聘人职位(如：HR)',
  `contact` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '联系电话',
  `site` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '公司网址',
  `addrid` int(10) NOT NULL DEFAULT '0' COMMENT '所在区域(site_area)',
  `address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '公司地址',
  `lng` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '经度',
  `lat` varchar(50) NOT NULL DEFAULT '' COMMENT '纬度',
  `welfare` varchar(255) CHARACTER SET utf32 NOT NULL DEFAULT '' COMMENT '公司福利(jobitem)',
  `body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '公司简介',
  `work_time_s` varchar(50) NOT NULL DEFAULT '' COMMENT '工作时间_开始',
  `work_time_e` varchar(50) NOT NULL DEFAULT '' COMMENT '工作时间_结束',
  `rest_flag` int(1) NOT NULL DEFAULT '1' COMMENT '休息{1.双休，2.单休}',
  `work_over` int(1) NOT NULL DEFAULT '2' COMMENT '加班{1.加班，2.不加班}',
  `pics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '公司相册图集',
  `weight` int(10) NOT NULL DEFAULT '0' COMMENT '排序值，越大越在前（默认0）',
  `state` int(1) NOT NULL DEFAULT '0' COMMENT '审核状态{0.待审核，1.审核通过，2.审核拒绝}',
  `pubdate` int(10) NOT NULL DEFAULT '0' COMMENT '发布时间',
  `full_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '工商_企业全称',
  `enterprise_type` varchar(1024) NOT NULL DEFAULT '' COMMENT '工商_企业类型',
  `enterprise_establish` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '工商_企业成立日期',
  `enterprise_money` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '工商_注册资金',
  `enterprise_people` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '工商_法定代表人',
  `enterprise_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '工商_社会信用代码',
  `business_license` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '工商_营业执照',
  `changeState` int(1) NOT NULL DEFAULT '0' COMMENT '敏感信息待审核',
  `changeContent` varchar(1000) NOT NULL DEFAULT '' COMMENT '敏感信息内容',
  `changeGs` int(1) NOT NULL DEFAULT '0' COMMENT '是否手动修改过工商信息',
  `property` varchar(100) NOT NULL DEFAULT '' COMMENT '属性(jobitem)（如紧急）',
  `famous` int(1) NOT NULL DEFAULT '0' COMMENT '是否名企',
  `certification` int(1) NOT NULL DEFAULT '0' COMMENT '是否已认证{0.未认证，1.已认证}',
  `combo_id` int(11) NOT NULL DEFAULT '0' COMMENT '当前套餐id(job_combo)',
  `combo_enddate` int(10) NOT NULL DEFAULT '0' COMMENT '当前套餐结束时间',
  `combo_job` int(4) NOT NULL DEFAULT '0' COMMENT '套餐可上架职位总数（使用量查sql可得剩余量）',
  `combo_resume` int(4) NOT NULL DEFAULT '0' COMMENT '套餐每天下载简历数',
  `combo_refresh` int(4) NOT NULL DEFAULT '0' COMMENT '套餐每天可刷新职位数',
  `combo_top` int(11) NOT NULL DEFAULT '0' COMMENT '套餐置顶剩余时长（因可以封存，不记录总量，总量联查套餐得到）',
  `combo_wait` varchar(1000) NOT NULL DEFAULT '' COMMENT '待生效套餐字符串',
  `package_job` int(11) NOT NULL DEFAULT '0' COMMENT '增值包上架职位剩余数（一次性、永久）',
  `package_resume` int(11) NOT NULL DEFAULT '0' COMMENT '增值包简历剩余下载数（一次性、永久）',
  `package_refresh` int(11) NOT NULL DEFAULT '0' COMMENT '增值包职位剩余刷新数（一次性、永久）',
  `package_top` int(11) NOT NULL DEFAULT '0' COMMENT '增值包置顶剩余总时长（一次性、永久）',
  `complete` int(1) NOT NULL DEFAULT '0' COMMENT '信息是否已经全部完善{0.待完善，1.已完善}',
  `need_complete` int(1) NOT NULL DEFAULT '0' COMMENT '必填项是否已全部填完',
  `ae_jobs_count` int(11) NOT NULL DEFAULT '0' COMMENT '近期更新的职位数',
  `promotion` int(1) NOT NULL DEFAULT '0' COMMENT '推广置顶{0.否，1.是}',
  `pgactive` int(10) NOT NULL DEFAULT '0' COMMENT '最后更新的普工信息时间',
  `personalize` varchar(60) NOT NULL DEFAULT '' COMMENT '个性化设置',
  `sms_delivery` int(1) NOT NULL DEFAULT '0' COMMENT '短信_投递简历通知',
  `sms_onlineNotice` int(1) NOT NULL DEFAULT '0' COMMENT '短信_在线消息通知',
  `sms_interviewRefuse` int(1) NOT NULL DEFAULT '0' COMMENT '短信_面试取消通知',
  `sms_fair` int(1) NOT NULL DEFAULT '0' COMMENT '短信_招聘会通知',
  `email_delivery` int(1) NOT NULL DEFAULT '0' COMMENT '邮件_投递简历通知',
  `email_fair` int(1) NOT NULL DEFAULT '0' COMMENT '邮件_招聘会通知',
  `delivery_limit_interval` int(11) NOT NULL DEFAULT '3' COMMENT '投递间隔限制【单位：月】',
  `delivery_limit_certifyState` int(11) NOT NULL DEFAULT '1' COMMENT '投递限制：实名认证',
  `delivery_limit_phoneCheck` int(11) NOT NULL DEFAULT '1' COMMENT '投递限制：手机认证',
  `delivery_refuse` varchar(1024) NOT NULL DEFAULT '{"experience":"-1","salary":"-1","education":"-1","min_age":"-1","max_age":"-1","complete":"60"}' COMMENT '投递自动拒绝',
  `delivery_filter` int(1) NOT NULL DEFAULT '1' COMMENT '投递初筛开关【默认是开，即1】',
  `admin` int(11) NOT NULL DEFAULT '0' COMMENT '管理员',
  `delivery_smart` int(11) NOT NULL DEFAULT '0' COMMENT '智能处理【默认0，更新过则为1】',
  `tag` varchar(60) NOT NULL DEFAULT '' COMMENT '管理员标签',
  `refuse` varchar(255) NOT NULL DEFAULT '' COMMENT '拒审原因',
  `email_buyResume` int(1) NOT NULL DEFAULT '0' COMMENT '购买简历发送到邮件',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT '企业邮箱，接收投递的简历',
  PRIMARY KEY (`id`),
  KEY `title` (`title`),
  KEY `nature` (`nature`),
  KEY `userid` (`userid`),
