DROP TABLE IF EXISTS `hn_member`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hn_member` (
  `id` bigint(10) NOT NULL AUTO_INCREMENT,
  `mtype` int(1) NOT NULL DEFAULT '1' COMMENT '会员类型',
  `username` varchar(50) NOT NULL DEFAULT '' COMMENT '用户名',
  `password` varchar(47) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '登录密码',
  `level` int(10) NOT NULL DEFAULT '0' COMMENT '等级',
  `expired` int(10) NOT NULL DEFAULT '0' COMMENT '过期时间',
  `last_level` int(10) NOT NULL DEFAULT '0' COMMENT '最后开通的会员等级',
  `last_expired` int(10) NOT NULL DEFAULT '0' COMMENT '最后开通会员的过期时间',
  `discount` varchar(60) NOT NULL DEFAULT '' COMMENT '打折卡',
  `nickname` varchar(36) NOT NULL DEFAULT '' COMMENT '昵称',
  `nickname_audit` varchar(36) NOT NULL DEFAULT '' COMMENT '审核中的昵称',
  `nickname_state` varchar(50) NOT NULL DEFAULT '' COMMENT '昵称审核状态',
  `realname` varchar(200) NOT NULL DEFAULT '' COMMENT '真实姓名',
  `idcard` varchar(100) NOT NULL DEFAULT '' COMMENT '身份证号码',
  `idcardFront` varchar(255) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '身份证正面照片',
  `idcardBack` varchar(255) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '身份证反面照片',
  `certifyState` int(1) NOT NULL DEFAULT '0' COMMENT '实名认证',
  `certifyInfo` varchar(200) NOT NULL DEFAULT '' COMMENT '认证备注',
  `email` varchar(150) NOT NULL DEFAULT '' COMMENT '联系邮箱',
  `emailCheck` int(1) NOT NULL DEFAULT '0' COMMENT '邮箱验证',
  `sendEmail` int(10) NOT NULL DEFAULT '0' COMMENT '发送邮件验证时间',
  `areaCode` varchar(10) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '手机区域代码',
  `phone` varchar(100) NOT NULL DEFAULT '' COMMENT '联系电话',
  `phoneCheck` int(1) NOT NULL DEFAULT '0' COMMENT '手机验证',
  `phoneBindTime` int(10) NOT NULL DEFAULT '0' COMMENT '绑定时间',
  `sendPhone` int(10) NOT NULL DEFAULT '0' COMMENT '发送手机验证时间',
  `paypwd` varchar(47) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '支付密码',
  `paypwdCheck` int(1) NOT NULL DEFAULT '0' COMMENT '支付密码验证',
  `qq` varchar(11) NOT NULL DEFAULT '' COMMENT '联系QQ',
  `photo` varchar(255) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '头像',
  `photo_audit` varchar(200) NOT NULL DEFAULT '' COMMENT '审核中的头像',
  `photo_state` varchar(50) NOT NULL DEFAULT '' COMMENT '头像审核状态',
  `sex` int(1) NOT NULL DEFAULT '1' COMMENT '性别',
  `birthday` varchar(10) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '出生日期',
  `mgroupid` int(10) NOT NULL DEFAULT '0' COMMENT '管理组',
  `company` varchar(100) NOT NULL DEFAULT '' COMMENT '公司名称',
  `cityid` int(10) NOT NULL DEFAULT '0' COMMENT '城市分站ID',
  `addr` int(10) NOT NULL DEFAULT '0' COMMENT '所在区域',
  `address` text COMMENT '联系地址',
  `license` varchar(255) NOT NULL DEFAULT '' COMMENT '营业执照',
  `licenseState` int(1) NOT NULL DEFAULT '0' COMMENT '营业执照认证',
  `licenseInfo` varchar(200) NOT NULL DEFAULT '' COMMENT '认证备注',
  `regtime` int(10) NOT NULL DEFAULT '0' COMMENT '注册时间',
  `regip` varchar(15) NOT NULL DEFAULT '' COMMENT '注册IP',
  `regipaddr` varchar(30) NOT NULL DEFAULT '' COMMENT 'IP详细地址',
  `money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '帐户余额',
  `freeze` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '冻结金额',
  `point` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '积分',
  `bonus` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '账户消费金',
  `promotion` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '保障金',
  `recid` int(10) NOT NULL DEFAULT '0' COMMENT '推广会员ID',
  `recfan` int(1) NOT NULL DEFAULT '0' COMMENT '是否已返现',
  `rectime` int(10) NOT NULL DEFAULT '0' COMMENT '返现时间',
  `online` int(10) NOT NULL DEFAULT '0' COMMENT '是否在线',
  `tempbg` int(10) NOT NULL DEFAULT '0' COMMENT '自定义背景图片',
  `pctempbg` int(10) NOT NULL DEFAULT '0' COMMENT 'pc端个人中心背景图',
  `mtempbgurl` varchar(255) NOT NULL DEFAULT '' COMMENT '手机端个人主页背景图url',
  `state` int(1) NOT NULL DEFAULT '0' COMMENT '会员状态',
  `stateinfo` varchar(200) NOT NULL DEFAULT '' COMMENT '审核备注',
  `regfrom` varchar(20) NOT NULL DEFAULT '' COMMENT '注册来源',
  `logincount` int(10) NOT NULL DEFAULT '0' COMMENT '登录次数',
  `lastlogintime` int(10) NOT NULL DEFAULT '0' COMMENT '最后登录时间',
  `lastloginip` varchar(15) NOT NULL DEFAULT '' COMMENT '最后登录IP',
  `lastloginipaddr` varchar(100) NOT NULL DEFAULT '' COMMENT 'IP详细地址',
  `qq_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'qq快捷登录',
  `sina_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '新浪微博快捷登录',
  `baidu_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '百度快捷登录',
  `alipay_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '支付宝快捷登录',
  `tqq_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '腾讯微博快捷登录',
  `renren_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '人人快捷登录',
  `douban_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '豆瓣快捷登录',
  `facebook_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'facebook快捷登录',
  `wechat_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '微信快捷登录',
  `wechat_openid` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '微信openid',
  `wechat_mini_openid` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '小程序openid',
  `wechat_mini_session` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '小程序登陆session',
  `douyin_conn` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '抖音快捷登录',
  `douyin_openid` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '抖音openid',
  `expired_notify_day` int(1) NOT NULL DEFAULT '0' COMMENT '到期前一天提醒',
  `expired_notify_week` int(1) NOT NULL DEFAULT '0' COMMENT '到期前一周提醒',
  `expired_notify_month` int(1) NOT NULL DEFAULT '0' COMMENT '到期前一月提醒',
  `purviews` text COMMENT '权限',
  `sourceclient` text COMMENT '来源客户端',
  `from_uid` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '分享人uid',
  `alicard` char(50) CHARACTER SET utf8 DEFAULT '' COMMENT '支付宝账号',
  `notice` int(1) NOT NULL DEFAULT '0' COMMENT '1-接收通知,0-不接受',
  `lng` varchar(100) NOT NULL DEFAULT '' COMMENT '经度',
  `lat` varchar(100) NOT NULL DEFAULT '' COMMENT '纬度',
  `wechat_subscribe` int(1) NOT NULL DEFAULT '0' COMMENT '是否已关注微信公众号',
  `delivery_count` int(1) unsigned NOT NULL DEFAULT '0' COMMENT '配送费优惠剩余次数',
  `is_cancellation` int(1) NOT NULL DEFAULT '0' COMMENT '是否申请注销',
  `description` varchar(200) NOT NULL DEFAULT '' COMMENT '个人简介',
  `is_editname` int(1) NOT NULL DEFAULT '0' COMMENT '是否修改过名字',
  `noawardlegoutime` varchar(20) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '禁止参与有奖乐购时间',
  `is_noawardlegou` int(1) NOT NULL DEFAULT '0' COMMENT '是否乐购拉黑',
  `hidePackage` varchar(255) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '隐藏的模块',
  `sortPackage` varchar(255) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '模块排序',
  `lock_cityid` int(1) NOT NULL DEFAULT '0' COMMENT '锁定分站',
  `im_unread_count` int(10) NOT NULL DEFAULT '0' COMMENT 'IM即时通讯未读消息数量',
  `robot` int(1) unsigned NOT NULL DEFAULT '0' COMMENT '虚拟账号',
  `access_token_wxmini` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '微信小程序api令牌',
  `refresh_token_wxmini` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '微信小程序api刷新令牌',
  `access_token_android` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '安卓app端api令牌',
  `refresh_token_android` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '安卓app端api刷新令牌',
  `access_token_ios` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '苹果app端api令牌',
  `refresh_token_ios` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '苹果app端api刷新令牌',
  `access_token_harmony` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '鸿蒙app端api令牌',
  `refresh_token_harmony` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '鸿蒙app端api刷新令牌',
  `nation` varchar(50) NOT NULL DEFAULT '' COMMENT '民族',
  `admin_common_module` text COMMENT '管理员常用模块',
  `admin_common_function` text COMMENT '管理员常用功能',
  `admin_collection_function` text COMMENT '管理员收藏功能',
  `access_token_dymini` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '抖音小程序api令牌',
  `refresh_token_dymini` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '抖音小程序api刷新令牌',
  `zhaopin_company` int(1) unsigned NOT NULL DEFAULT '1' COMMENT '是否已经入驻城市招聘企业 1:未入驻 2:已入驻',
  `zhaopin_resume` int(1) unsigned NOT NULL DEFAULT '1' COMMENT '是否已经注册城市招聘简历 1:未注册 2:已注册',
  `wechat_app_openid` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'APP端的微信openid',
  PRIMARY KEY (`id`),
  KEY `username` (`username`),
  KEY `nickname` (`nickname`),
  KEY `email` (`email`),
  KEY `discount` (`discount`),
  KEY `phone` (`phone`),
  KEY `company` (`company`),
  KEY `mtype` (`mtype`),
  KEY `online` (`online`),
  KEY `state` (`state`),
  KEY `mgroupid` (`mgroupid`),
  KEY `wechat_conn` (`wechat_conn`),
  KEY `wechat_openid` (`wechat_openid`),
  KEY `wechat_mini_openid` (`wechat_mini_openid`),
  KEY `cityid` (`cityid`),
  KEY `addr` (`addr`),
  KEY `level` (`level`),
  KEY `expired` (`expired`),
  KEY `licenseState` (`licenseState`),
  KEY `recid` (`recid`),
  KEY `from_uid` (`from_uid`),
  KEY `is_cancellation` (`is_cancellation`),
  KEY `password` (`password`),
  KEY `money` (`money`),
  KEY `point` (`point`),
  KEY `bonus` (`bonus`),
  KEY `access_token_wxmini` (`access_token_wxmini`),
  KEY `refresh_token_wxmini` (`refresh_token_wxmini`),
  KEY `access_token_android` (`access_token_android`),
  KEY `refresh_token_android` (`refresh_token_android`),
  KEY `access_token_ios` (`access_token_ios`),
  KEY `refresh_token_ios` (`refresh_token_ios`),
  KEY `wechat_subscribe` (`wechat_subscribe`),
  KEY `certifyState` (`certifyState`),
  KEY `nickname_audit` (`nickname_audit`),
  KEY `robot` (`robot`),
  KEY `photo_audit` (`photo_audit`),
  KEY `zhaopin_company` (`zhaopin_company`),
  KEY `zhaopin_resume` (`zhaopin_resume`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='网站会员';
