DROP TABLE IF EXISTS `hn_shop_store`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hn_shop_store` (
  `id` bigint(10) NOT NULL AUTO_INCREMENT,
  `cityid` int(10) NOT NULL DEFAULT '0' COMMENT '城市ID',
  `title` varchar(60) NOT NULL DEFAULT '' COMMENT '店铺名',
  `domaintype` int(1) NOT NULL DEFAULT '0' COMMENT '域名类型',
  `company` varchar(60) NOT NULL DEFAULT '' COMMENT '公司名称',
  `referred` varchar(20) NOT NULL DEFAULT '' COMMENT '简称',
  `addrid` int(10) NOT NULL DEFAULT '0' COMMENT '所在地',
  `address` varchar(100) NOT NULL DEFAULT '' COMMENT '地址',
  `industry` int(10) NOT NULL DEFAULT '0' COMMENT '经营行业',
  `project` varchar(100) NOT NULL DEFAULT '' COMMENT '主营项目',
  `logo` varchar(255) NOT NULL DEFAULT '' COMMENT '店铺logo',
  `userid` int(10) NOT NULL DEFAULT '0' COMMENT '所属用户',
  `people` varchar(30) NOT NULL DEFAULT '' COMMENT '联系人',
  `contact` varchar(30) NOT NULL DEFAULT '' COMMENT '联系电话',
  `tel` varchar(30) NOT NULL DEFAULT '' COMMENT '客服电话',
  `qq` varchar(30) NOT NULL DEFAULT '' COMMENT '客服QQ',
  `note` text COMMENT '店铺简介',
  `click` int(10) NOT NULL DEFAULT '0' COMMENT '浏览次数',
  `weight` int(10) NOT NULL DEFAULT '0' COMMENT '排序',
  `state` int(1) NOT NULL DEFAULT '0' COMMENT '店铺状态',
  `certi` int(1) NOT NULL DEFAULT '0' COMMENT '认证',
  `rec` int(1) NOT NULL DEFAULT '0' COMMENT '推荐',
  `pubdate` int(10) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `video` varchar(255) NOT NULL DEFAULT '' COMMENT '视频',
  `store_switch` int(1) NOT NULL DEFAULT '0' COMMENT '开关',
  `shop_openid` varchar(40) NOT NULL DEFAULT '' COMMENT '扩展id',
  `wechatcode` varchar(100) NOT NULL DEFAULT '' COMMENT '微信号',
  `wechatqr` varchar(100) NOT NULL DEFAULT '' COMMENT '微信二维码',
  `pic` text COMMENT '图片',
  `bind_print` int(1) NOT NULL DEFAULT '0' COMMENT '开启打印机',
  `lng` varchar(50) NOT NULL DEFAULT '' COMMENT '纬度',
  `lat` varchar(50) NOT NULL DEFAULT '' COMMENT '经度',
  `distribution` int(1) NOT NULL DEFAULT '0' COMMENT '骑手配送',
  `express` int(1) NOT NULL DEFAULT '0' COMMENT '快递',
  `merchant_deliver` int(1) NOT NULL DEFAULT '0' COMMENT '商家自配',
  `delivery` int(1) NOT NULL DEFAULT '0' COMMENT '是否支持货到付款',
  `shopFee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '商城佣金',
  `shoptype` smallint(1) NOT NULL DEFAULT '0' COMMENT '商城类型,1-电商,2-团购',
  `businessday` varchar(255) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '营业日',
  `period` text CHARACTER SET utf8mb4 COMMENT '时间段(电商:客服时间,团购:营业时间)',
  `facility` text COMMENT '团购设施',
  `explosion` varchar(255) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '爆款推荐',
  `madvertise` text CHARACTER SET utf8mb4 COMMENT '手机端广告',
  `padvertise` text CHARACTER SET utf8mb4 COMMENT 'PC端广告',
  `authattrtype` varchar(255) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '商家资质类型',
  `authattrparam` text CHARACTER SET utf8mb4 COMMENT '商家资质',
  `psaudit` smallint(1) NOT NULL DEFAULT '0' COMMENT '更改销售类型状态,1-申请审核',
  `litpic` varchar(255) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '主图',
  `start_time1` varchar(5) NOT NULL DEFAULT '' COMMENT '营业开始时间',
  `end_time1` varchar(5) NOT NULL DEFAULT '' COMMENT '营业结束时间',
  `start_time2` varchar(5) NOT NULL DEFAULT '' COMMENT '营业开始时间',
  `end_time2` varchar(5) NOT NULL DEFAULT '' COMMENT '营业结束时间',
  `start_time3` varchar(5) NOT NULL DEFAULT '' COMMENT '营业开始时间',
  `end_time3` varchar(5) NOT NULL DEFAULT '' COMMENT '营业结束时间',
  `circle` char(50) NOT NULL DEFAULT '' COMMENT '所在商圈',
  `peisongstate` smallint(1) NOT NULL DEFAULT '0' COMMENT '修改店铺配送方式',
  `toshop` smallint(1) NOT NULL DEFAULT '0' COMMENT '到店消费',
  `pcount` int(10) NOT NULL DEFAULT '0' COMMENT '商品数量',
  `refuse` varchar(255) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '拒审原因',
  PRIMARY KEY (`id`),
  KEY `title` (`title`),
  KEY `company` (`company`),
  KEY `addrid` (`addrid`),
  KEY `industry` (`industry`),
  KEY `userid` (`userid`),
  KEY `cityid` (`cityid`),
  KEY `pubdate` (`pubdate`),
  KEY `people` (`people`),
  KEY `contact` (`contact`),
  KEY `state` (`state`),
  KEY `store_switch` (`store_switch`),
  KEY `bind_print` (`bind_print`),
  KEY `lng` (`lng`),
  KEY `lat` (`lat`),
  KEY `distribution` (`distribution`),
  KEY `express` (`express`),
  KEY `merchant_deliver` (`merchant_deliver`),
  KEY `delivery` (`delivery`),
  KEY `shoptype` (`shoptype`),
  KEY `certi` (`certi`),
  KEY `pcount` (`pcount`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='商城店铺';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `hn_shop_store`
--

LOCK TABLES `hn_shop_store` WRITE;
/*!40000 ALTER TABLE `hn_shop_store` DISABLE KEYS */;
/*!40000 ALTER TABLE `hn_shop_store` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `hn_shop_tuanpin`
--

DROP TABLE IF EXISTS `hn_shop_tuanpin`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hn_shop_tuanpin` (
  `id` bigint(10) NOT NULL AUTO_INCREMENT,
  `oid` varchar(18) NOT NULL DEFAULT '0' COMMENT '订单id',
  `hid` int(10) NOT NULL DEFAULT '0' COMMENT '活动id',
  `proid` int(10) NOT NULL DEFAULT '0' COMMENT '商品id',
  `userid` int(10) NOT NULL DEFAULT '0' COMMENT '创建人',
  `pubdate` int(10) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `state` int(1) NOT NULL DEFAULT '0' COMMENT '状态 1:正常 2:失效 3:成功 4:退款中',
  `people` int(4) NOT NULL DEFAULT '0' COMMENT '已参加人数',
  `enddate` int(10) NOT NULL DEFAULT '0' COMMENT '结束时间',
  `okdate` int(10) NOT NULL DEFAULT '0' COMMENT '成团时间',
  `user` varchar(100) NOT NULL DEFAULT '' COMMENT '成员ID',
  PRIMARY KEY (`id`),
  KEY `oid` (`oid`),
  KEY `state` (`state`),
  KEY `hid` (`hid`),
  KEY `proid` (`proid`),
  KEY `userid` (`userid`),
  KEY `enddate` (`enddate`),
  KEY `okdate` (`okdate`),
  KEY `user` (`user`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='商城团购拼团';
/*!40101 SET character_set_client = @saved_cs_client */;

