-- Dumping data for table `hn_shop_tuanpin`
--

LOCK TABLES `hn_shop_tuanpin` WRITE;
/*!40000 ALTER TABLE `hn_shop_tuanpin` DISABLE KEYS */;
/*!40000 ALTER TABLE `hn_shop_tuanpin` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `hn_shop_type`
--

DROP TABLE IF EXISTS `hn_shop_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hn_shop_type` (
  `id` bigint(5) NOT NULL AUTO_INCREMENT,
  `parentid` int(5) unsigned NOT NULL DEFAULT '0' COMMENT '上级分类ID',
  `typename` varchar(30) NOT NULL DEFAULT '' COMMENT '分类名称',
  `weight` int(5) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `seotitle` varchar(80) NOT NULL DEFAULT '' COMMENT 'SEO标题',
  `keywords` varchar(60) NOT NULL DEFAULT '' COMMENT 'seo关键字',
  `description` varchar(150) NOT NULL DEFAULT '' COMMENT 'seo描述',
  `spe` varchar(255) NOT NULL DEFAULT '' COMMENT '关联规格',
  `pubdate` int(10) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `icon` varchar(255) NOT NULL DEFAULT '' COMMENT '图标',
  PRIMARY KEY (`id`),
  KEY `parentid` (`parentid`),
  KEY `typename` (`typename`)
) ENGINE=MyISAM AUTO_INCREMENT=335 DEFAULT CHARSET=utf8 COMMENT='商城分类';
/*!40101 SET character_set_client = @saved_cs_client */;

