  `title` varchar(30) NOT NULL DEFAULT '' COMMENT '模块名',
  `name` varchar(30) NOT NULL DEFAULT '' COMMENT '英文识别码',
  `icon` varchar(200) NOT NULL DEFAULT '' COMMENT '图标',
  `note` text COMMENT '模块描述',
  `state` int(1) NOT NULL DEFAULT '0' COMMENT '状态',
  `weight` int(5) NOT NULL DEFAULT '0' COMMENT '排序',
  `subnav` text COMMENT '子级菜单',
