  `domainRules` text COMMENT '一级、二级域名规则',
  `catalogRules` text COMMENT '子目录规则',
  `installsql` mediumtext COMMENT '安装',
  `insertsql` mediumtext COMMENT '初始数据',
  `delsql` text COMMENT '卸载',
  `version` varchar(30) NOT NULL DEFAULT '' COMMENT '版本号',
  `date` int(10) NOT NULL DEFAULT '0' COMMENT '安装时间',
  `wx` int(1) NOT NULL DEFAULT '0' COMMENT '微信小程序开关',
  `bold` int(1) NOT NULL DEFAULT '0' COMMENT '加粗',
  `target` int(1) NOT NULL DEFAULT '0' COMMENT '新窗口',
  `color` varchar(7) NOT NULL DEFAULT '' COMMENT '颜色',
  `link` varchar(255) NOT NULL DEFAULT '' COMMENT '链接',
  `subject` varchar(30) NOT NULL DEFAULT '' COMMENT '自定义标题',
  `app` int(1) NOT NULL DEFAULT '0' COMMENT 'app开关',
  `bd` int(1) NOT NULL DEFAULT '0' COMMENT '百度小程序开关',
  `qm` int(1) NOT NULL DEFAULT '0' COMMENT 'QQ小程序开关',
  `dy` int(1) NOT NULL DEFAULT '0' COMMENT '抖音小程序开关',
  `pc` int(1) NOT NULL DEFAULT '1' COMMENT 'PC端开关',
  `h5` int(1) NOT NULL DEFAULT '1' COMMENT 'H5端开关',
  `harmony` int(1) NOT NULL DEFAULT '0' COMMENT '鸿蒙端',
  `ios` int(1) NOT NULL DEFAULT '0' COMMENT '苹果端',
  `android` int(1) NOT NULL DEFAULT '0' COMMENT '安卓端',
  PRIMARY KEY (`id`),
  KEY `state` (`state`),
  KEY `type` (`type`),
  KEY `parentid` (`parentid`),
  KEY `weight` (`weight`)
) ENGINE=MyISAM AUTO_INCREMENT=32 DEFAULT CHARSET=utf8 COMMENT='系统模块管理';
