CREATE TABLE `hn_site_verify` (
  `id` bigint(10) NOT NULL AUTO_INCREMENT,
  `module` varchar(10) NOT NULL DEFAULT '' COMMENT '平台分类',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT '会员ID',
  `type` varchar(15) NOT NULL DEFAULT '' COMMENT '类型',
  `account` varchar(50) NOT NULL DEFAULT '' COMMENT '发送的号码',
  `code` varchar(10) NOT NULL DEFAULT '' COMMENT '验证码',
  `body` text COMMENT '发送内容',
  `time` int(10) NOT NULL DEFAULT '0' COMMENT '发送时间',
  `ip` varchar(15) NOT NULL DEFAULT '' COMMENT '发送ip',
  PRIMARY KEY (`id`),
  KEY `module` (`module`),
  KEY `uid` (`uid`),
  KEY `type` (`type`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='验证码发送记录';
